package com.multiaceites.controller; import com.multiaceites.dto.UserRequest; import com.multiaceites.service.UserService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/usuarios") @RequiredArgsConstructor @PreAuthorize("hasRole('ADMIN')") public class UserController{private final UserService s;@GetMapping public Object all(){return s.all();}@PostMapping public Object save(@Valid @RequestBody UserRequest r){return s.save(r);}@PutMapping("/{id}") public Object update(@PathVariable Long id,@Valid @RequestBody UserRequest r){return s.update(id,r);}@DeleteMapping("/{id}") public void delete(@PathVariable Long id){s.delete(id);}}
